#!/usr/bin/env python3
"""Original clean-room reimplementation of the observed eureka CLI behavior."""
import json
import os
import subprocess
import sys
from json import JSONDecodeError

APP = "eureka"
VERSION = "2.0.0"

SETUP_TEXT = (
    "\x1b[0m\x1b[33m"
    "############################################################\n"
    "####                  First Time Setup                  ####\n"
    "############################################################\n"
    "\n"
    "This tool requires you to have a repository with a README.md\n"
    "in the root folder. The markdown file is where your ideas\n"
    "will be stored.\n"
    "\n"
    "Once first time setup has completed, simply run Eureka again\n"
    "to begin writing down ideas.\n"
    "        \n"
    "\x1b[0m"
)


def prog_name() -> str:
    return os.path.basename(sys.argv[0]) or "executable"


def help_text() -> str:
    return (
        "Input and store your ideas without leaving the terminal\n"
        "\n"
        f"Usage: {prog_name()} [OPTIONS]\n"
        "\n"
        "Options:\n"
        "      --clear-config  Clear your stored configuration\n"
        "  -v, --view          View ideas with your $PAGER env variable. If unset use less\n"
        "  -h, --help          Print help\n"
        "  -V, --version       Print version\n"
    )


def usage_error(message: str) -> int:
    sys.stderr.write(
        f"error: {message}\n\n"
        f"Usage: {prog_name()} [OPTIONS]\n\n"
        "For more information, try '--help'.\n"
    )
    return 2


def parse_args(argv):
    seen_view = False
    seen_clear = False
    view = False
    clear = False
    end_opts = False
    for arg in argv:
        if end_opts:
            return ("err", f"unexpected argument '{arg}' found")
        if arg == "--":
            end_opts = True
            continue
        if arg == "--help":
            return ("help", None)
        if arg == "--version":
            return ("version", None)
        if arg == "--view":
            if seen_view:
                return ("err", "the argument '--view' cannot be used multiple times")
            seen_view = True
            view = True
            continue
        if arg == "--clear-config":
            if seen_clear:
                return ("err", "the argument '--clear-config' cannot be used multiple times")
            seen_clear = True
            clear = True
            continue
        if arg.startswith("--"):
            return ("err", f"unexpected argument '{arg}' found")
        if arg.startswith("-") and arg != "-":
            for ch in arg[1:]:
                if ch == "h":
                    return ("help", None)
                if ch == "V":
                    return ("version", None)
                if ch == "v":
                    if seen_view:
                        return ("err", "the argument '--view' cannot be used multiple times")
                    seen_view = True
                    view = True
                    continue
                return ("err", f"unexpected argument '-{ch}' found")
            continue
        return ("err", f"unexpected argument '{arg}' found")
    return ("run", {"view": view, "clear": clear})


def config_base() -> str:
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        return xdg
    home = os.environ.get("HOME")
    if home:
        return os.path.join(home, ".config")
    # A simple fallback for unusual environments.
    return os.path.join(os.path.expanduser("~"), ".config")


def config_path() -> str:
    return os.path.join(config_base(), APP, "config.json")


def error_text(exc) -> str:
    if isinstance(exc, FileNotFoundError):
        return "No such file or directory (os error 2)"
    if isinstance(exc, PermissionError):
        return "Permission denied (os error 13)"
    return str(exc)


def log_error(message: str):
    sys.stderr.write(f" ERROR eureka > {message}\n")


def load_config():
    path = config_path()
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = f.read()
    except FileNotFoundError:
        raise
    try:
        obj = json.loads(data)
    except JSONDecodeError as e:
        # serde_json-like wording for the common malformed inputs seen in probes.
        stripped = data.lstrip()
        if stripped and stripped[0].isalpha():
            raise ValueError("expected ident at line 1 column 2")
        raise ValueError(f"{e.msg} at line {e.lineno} column {e.colno}")
    repo = obj.get("repo", "") if isinstance(obj, dict) else ""
    return str(repo)


def save_config(repo: str):
    path = config_path()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump({"repo": repo}, f, separators=(",", ":"))


def green_prompt(text: str):
    sys.stdout.write(f"\x1b[0m\x1b[1m\x1b[32m{text}\n\x1b[0m> ")
    sys.stdout.flush()


def red_line(text: str):
    sys.stdout.write(f"\x1b[0m\x1b[31m{text}\n\x1b[0m")
    sys.stdout.flush()


def read_trimmed_line():
    line = sys.stdin.readline()
    if line == "":
        return None
    return line.strip()


def first_time_setup():
    sys.stdout.write(SETUP_TEXT)
    sys.stdout.flush()
    while True:
        green_prompt("Absolute path to your idea repo")
        val = read_trimmed_line()
        if val is None:
            # The original prompt library immediately re-prompts on EOF.
            continue
        if not os.path.isabs(val):
            red_line("Path must be absolute")
            continue
        try:
            save_config(val)
            sys.stdout.write("First time setup complete. Happy ideation!\n")
            sys.stdout.flush()
        except Exception as e:
            log_error(error_text(e))
        return 0


def ask_summary() -> str:
    while True:
        green_prompt(">> Idea summary")
        val = read_trimmed_line()
        if val is None:
            continue
        if val == "":
            continue
        return val


def run_editor(readme: str):
    editor = os.environ.get("EDITOR") or "vi"
    try:
        subprocess.run([editor, readme])
        return None
    except FileNotFoundError as e:
        return error_text(e)
    except OSError as e:
        return error_text(e)


def git_cmd(repo: str, args, check=False):
    try:
        p = subprocess.run(
            ["git", "-C", repo] + list(args),
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except FileNotFoundError as e:
        if check:
            raise RuntimeError(error_text(e))
        return 127
    if check and p.returncode != 0:
        raise RuntimeError("git command failed")
    return p.returncode


def has_head(repo: str) -> bool:
    return git_cmd(repo, ["rev-parse", "--verify", "HEAD"]) == 0


def branch_exists(repo: str, name: str) -> bool:
    return git_cmd(repo, ["show-ref", "--verify", "--quiet", f"refs/heads/{name}"]) == 0


def ensure_main(repo: str):
    # Opening a Repository with a missing path in git2 produced this wording.
    if not os.path.isdir(repo):
        raise RuntimeError(f"failed to resolve path '{repo}': No such file or directory; class=Os (2); code=NotFound (-3)")
    if not os.path.isdir(os.path.join(repo, ".git")) and git_cmd(repo, ["rev-parse", "--git-dir"]) != 0:
        raise RuntimeError(f"failed to resolve path '{repo}': No such file or directory; class=Os (2); code=NotFound (-3)")
    if not has_head(repo):
        # Observed for an unborn main branch.
        raise RuntimeError("reference 'refs/heads/main' not found; class=Reference (4); code=UnbornBranch (-9)")
    if branch_exists(repo, "main"):
        rc = git_cmd(repo, ["checkout", "main"])
    else:
        rc = git_cmd(repo, ["checkout", "-b", "main"])
    if rc != 0:
        # The most common failure is a dirty-file checkout conflict.
        raise RuntimeError("1 conflict prevents checkout; class=Checkout (20); code=Conflict (-13)")


def commit_idea(repo: str, summary: str):
    readme = os.path.join(repo, "README.md")
    # Match observed ordering: editor before switching/committing to main.
    editor_err = run_editor(readme)

    sys.stdout.write("Adding and committing your new idea to main..\n")
    sys.stdout.flush()

    ensure_main(repo)
    if not os.path.exists(readme):
        raise RuntimeError("No such file or directory (os error 2)")
    if git_cmd(repo, ["add", "README.md"]) != 0:
        raise RuntimeError("No such file or directory (os error 2)")

    rc = git_cmd(repo, ["commit", "--allow-empty", "-m", summary])
    if rc != 0:
        # A broad but readable approximation for unusual git configuration failures.
        raise RuntimeError("failed to create commit; class=Object (11); code=Generic (-1)")

    sys.stdout.write("Added and committed!\n")
    sys.stdout.write("Pushing your new idea..\n")
    sys.stdout.flush()

    # If editor could not be spawned, the original surfaced that OS error after
    # the normal status text in simple probes. Preserve that flavor.
    if editor_err:
        raise RuntimeError(editor_err)

    # Detect missing origin so the message matches libgit2 instead of git(1).
    if git_cmd(repo, ["remote", "get-url", "origin"]) != 0:
        raise RuntimeError("remote 'origin' does not exist; class=Config (7); code=NotFound (-3)")
    rc = git_cmd(repo, ["push", "origin", "main"])
    if rc != 0:
        raise RuntimeError("failed to push some refs; class=Net (12); code=Generic (-1)")
    sys.stdout.write("Pushed!\n")
    sys.stdout.flush()


def capture_idea(repo: str):
    summary = ask_summary()
    try:
        commit_idea(repo, summary)
    except Exception as e:
        log_error(str(e))
    return 0


def view_ideas(repo: str):
    readme = os.path.join(repo, "README.md")
    if not os.path.exists(readme):
        raise FileNotFoundError(readme)
    pager = os.environ.get("PAGER") or "less"
    try:
        subprocess.run([pager, readme])
    except FileNotFoundError as e:
        raise e


def clear_config():
    try:
        os.remove(config_path())
    except Exception as e:
        log_error(error_text(e))
    return 0


def main(argv):
    kind, data = parse_args(argv)
    if kind == "help":
        sys.stdout.write(help_text())
        return 0
    if kind == "version":
        sys.stdout.write(f"{APP} {VERSION}\n")
        return 0
    if kind == "err":
        return usage_error(data)

    opts = data
    if opts["clear"]:
        return clear_config()

    if opts["view"]:
        try:
            repo = load_config()
            view_ideas(repo)
        except Exception as e:
            log_error(error_text(e))
        return 0

    try:
        repo = load_config()
    except FileNotFoundError:
        return first_time_setup()
    except Exception as e:
        log_error(str(e))
        return 0
    return capture_idea(repo)


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
